```swift
class Solution {
    func rob(_ nums: [Int]) -> Int {
        var memo = Array(repeating: -1, count: nums.count)

        func dfs(_ i: Int) -> Int {
            if i >= nums.count {
                return 0
            }
            if memo[i] != -1 {
                return memo[i]
            }
            memo[i] = max(dfs(i + 1), nums[i] + dfs(i + 2))
            return memo[i]
